//! Runtime support for code generated by imping.
//!
//! Generated bindings depend on this crate alone. [`Module`], [`Global`] and
//! the string types also work without generated code.
//!
//! ```no_run
//! use imping_runtime::{Build, Global, Module};
//!
//! static TARGET: Module = Module::new(
//!     "target.exe",
//!     &[Build { timestamp: 0x64b8f2a1, image_size: 0xa2b000 }],
//! );
//! static GRAVITY: Global<f32> = Global::new(&TARGET, 0x3a1200);
//!
//! fn main() -> imping_runtime::Result<()> {
//!     // SAFETY: this build of `target.exe` keeps an `f32` at RVA 0x3a1200.
//!     unsafe { TARGET.init() }?;
//!     GRAVITY.write(4.9);
//!     Ok(())
//! }
//! ```
//!
//! # Main items
//!
//! - [`Module`]: a module's expected identity; [`Module::init`] checks the
//!   loaded build and resolves addresses against its base.
//! - [`Global`]: a typed global variable, read and written safely when it is
//!   [`Plain`].
//! - [`Hook`]: the guard a generated function's `hook` returns.
//! - [`CStrPtr`], [`WStrPtr`], [`CStrBuf`], [`WStrBuf`] and [`WString`]:
//!   `char` and `wchar_t` strings in the target's memory.
//! - [`Inherits`] and [`Upcast`]: base classes and pointer upcasts.
//! - [`Error`]: everything that can go wrong.
//!
//! # What stays `unsafe`
//!
//! [`Module::init`] is the one promise that the bindings match the running
//! build. After it, plain globals, hooks, forwarding a hooked call and
//! functions marked safe need no `unsafe`. Still `unsafe`, as only the caller
//! knows the target's state: dereferencing a pointer from the target, reading
//! a string through one, and calling a function not marked safe.
//!
//! Dereference once per block rather than once per access:
//!
//! ```no_run
//! # #[repr(C)] struct Entity { health: f32, armor: f32 }
//! # let player: *mut Entity = std::ptr::null_mut();
//! // SAFETY: `player` is null or points to a live entity owned by the target.
//! if let Some(player) = unsafe { player.as_mut() } {
//!     player.health = 100.0;
//!     player.armor = 50.0;
//! }
//! ```
//!
//! # Unloading
//!
//! Hooks jump into the mod's code, so drop or disable every [`Hook`] before
//! the mod is unloaded. After [`Hook::leak`], the mod must never be unloaded.
//!
//! # Platforms
//!
//! Windows only. Elsewhere the crate compiles, but [`Module::init`] returns
//! [`Error::UnsupportedPlatform`].

mod backend;
mod error;
mod global;
mod hook;
mod inherits;
mod module;
mod plain;
mod strings;
mod sys;

pub use crate::error::{Error, Result};
pub use crate::global::Global;
pub use crate::hook::Hook;
pub use crate::inherits::{Inherits, Upcast};
pub use crate::module::{Build, Module};
pub use crate::plain::Plain;
pub use crate::strings::{CStrBuf, CStrPtr, WStrBuf, WStrPtr, WString};

/// Plumbing for generated bindings; not a stable API, it changes with the
/// generator.
#[doc(hidden)]
pub mod __private {
    pub use crate::hook::{Slot, install};
}
